  session.ownerDefs = [...new Set([...(ownerDefs || []), defPath].filter(value => typeof value === 'string' && path.isAbsolute(value)).map(value => path.resolve(value)))];
  session.connectedAirBinding = connectedAirBinding || null;
  { const storedAppearance = loadCollisionAppearancePreference(); session.collisionAppearance = storedAppearance.value; session.collisionAppearanceConfigured = storedAppearance.configured; }
  session.collisionEditSourceAvailable = true; rotateCollisionEditSession(session);
