function scopeActions(text) { return parseAir(text).map((action, sourceOrder) => ({ number: action.number, sourceOrder, category: animationCategory(action.number) })); }

async function prepareAirActionSequenceSources(input) {
  const chosen = await input.chooseDestination(); if (!chosen) return null;
  if (Number.isInteger(input.currentAction()) && input.currentAction() !== Number(input.action)) throw new Error('The selected AIR Action changed while choosing the export folder. Reopen the export.');
  const airBytes = readBoundedStableFile(input.fs, input.airPath, MAX_EXACT_AIR_BYTES, 'AIR source'), sffBytes = readBoundedStableFile(input.fs, input.sffPath, MAX_AIR_SEQUENCE_SOURCE_BYTES, 'Connected SFF'), airText = airBytes.toString('utf8').replace(/^\uFEFF/, '');
  if (airBatchScope.sourceFingerprint(airText) !== String(input.sourceFingerprint || '')) throw new Error('The AIR changed after the export was requested. Reopen the export.');
  const matches = parseAir(airText).filter(item => item.number === Number(input.action));
  if (matches.length !== 1) throw new Error(matches.length ? `Action ${input.action} is duplicated. Choose an exact unique Action before exporting.` : `Action ${input.action} no longer exists.`);
  return { chosen, airBytes, sffBytes, action: matches[0], archive: parseSffBuffer(sffBytes, input.sffPath) };
}

async function chooseAirBatchScope(session, text, request = {}, title = 'Choose AIR animation scope') {
  const scopeSnapshot = airBatchScope.snapshot(text, scopeActions(text), session.airPath), marked = Array.isArray(request.markedActions) ? request.markedActions : [], visible = Array.isArray(request.visibleActions) ? request.visibleActions : [];
  if (request.sourceFingerprint && request.sourceFingerprint !== scopeSnapshot.fingerprint) throw new Error('The AIR source changed after the visible selection was captured. Reopen the action and review the current animation list.');
  while (true) {
    const workSets = assetWorkSets?.read('air-action', session.airPath) || [], currentWorkSets = workSets.filter(item => item.fingerprint === scopeSnapshot.fingerprint), staleWorkSets = workSets.length - currentWorkSets.length;
    const current = scopeSnapshot.entries.find(entry => entry.number === Number(request.currentAction)), group = current?.group || request.group;
    const choices = [
      ...(current ? [{ label: `Current animation (${current.number})`, mode: 'current' }] : []),
      ...(marked.length ? [{ label: `Marked animations (${marked.length})`, description: 'The current green-marked selection.', mode: 'marked' }] : []),
      ...(visible.length ? [{ label: `Visible / filtered animations (${visible.length})`, description: 'Exactly the action rows visible when this action was opened.', mode: 'visible' }] : []),
      ...(group ? [{ label: `Current category (${group})`, description: 'AIR uses its functional category as the shared Group scope.', mode: 'group' }] : []),
      { label: 'Action-number range…', description: 'Choose an inclusive numeric AIR action range.', mode: 'range' },
      ...(currentWorkSets.length ? [{ label: `Saved work set… (${currentWorkSets.length})`, description: staleWorkSets ? `${staleWorkSets} older set(s) are blocked until recreated.` : 'Reusable selection for this exact AIR revision.', mode: 'work-set' }] : []),
      ...(marked.length || visible.length ? [{ label: '$(save) Save selection as work set…', description: 'Saved for this project and this exact AIR revision.', mode: 'save-work-set' }] : []),
      { label: `All animations (${scopeSnapshot.entries.length})`, mode: 'all' }
    ];
    const picked = await vscode.window.showQuickPick(choices, { title, placeHolder: 'The current open AIR document is rechecked after review and before the edit.' }); if (!picked) return null;
    if (picked.mode === 'save-work-set') {
      const source = await vscode.window.showQuickPick([...(marked.length ? [{ label: `Marked animations (${marked.length})`, numbers: marked }] : []), ...(visible.length ? [{ label: `Visible / filtered animations (${visible.length})`, numbers: visible }] : [])], { title: 'Save which selection as a work set?' }); if (!source) continue;
      const name = await vscode.window.showInputBox({ title: 'Name this AIR work set', prompt: 'Use a short purpose such as Normals or Hit reactions.', validateInput: value => String(value).trim() ? undefined : 'Enter a name.' }); if (name === undefined) continue;
      const item = airBatchScope.createWorkSet(scopeSnapshot, name, source.numbers); await assetWorkSets.upsert('air-action', session.airPath, item); vscode.window.showInformationMessage(`Saved AIR work set “${item.name}” for this exact source revision.`); continue;
    }
    const scopeRequest = { mode: picked.mode, fingerprint: scopeSnapshot.fingerprint, currentAction: Number(request.currentAction), markedActions: marked, visibleActions: visible, group };
    if (picked.mode === 'range') { const value = await vscode.window.showInputBox({ title: 'Inclusive AIR action-number range', prompt: 'Enter first-last, for example 200-299.', value: current ? `${current.number}-${current.number}` : '', validateInput: input => /^\s*-?\d+\s*-\s*-?\d+\s*$/.test(input) ? undefined : 'Use first-last, for example 200-299.' }); if (value === undefined) continue; const match = /^\s*(-?\d+)\s*-\s*(-?\d+)\s*$/.exec(value); scopeRequest.first = Number(match[1]); scopeRequest.last = Number(match[2]); }
    if (picked.mode === 'work-set') { const item = await vscode.window.showQuickPick(currentWorkSets.map(value => ({ label: value.name, description: `${value.entryIds.length} animation(s)`, id: value.id })), { title: 'Choose a saved AIR work set' }); if (!item) continue; scopeRequest.workSetId = item.id; }
    try { return airBatchScope.resolveScope(scopeSnapshot, scopeRequest, workSets); } catch (error) { await vscode.window.showErrorMessage(`AIR scope is not safe to apply: ${error.message}`); }
  }
}

async function revealAirLine(session, line) {
  const document = await vscode.workspace.openTextDocument(session.airPath);
  const at = Math.max(0, line - 1);
  await showSourceWithAirEscape(session, document, { preserveFocus: false, preview: false, selection: new vscode.Range(at, 0, at, 0) });
}

async function replaceAirDocument(session, updated, authority = null) {
  const document = authority?.document || await vscode.workspace.openTextDocument(session.airPath);
  if (authority && (document.version !== authority.version || document.getText() !== authority.text)) throw new Error('The AIR source changed immediately before the edit. Review the current source and try again.');
  const lastLine = Math.max(0, document.lineCount - 1), edit = new vscode.WorkspaceEdit();
  edit.replace(document.uri, new vscode.Range(0, 0, lastLine, document.lineAt(lastLine).text.length), updated);
  if (!await vscode.workspace.applyEdit(edit)) throw new Error('VS Code rejected the AIR frame edit.');
  const current = vscode.workspace.textDocuments.find((item) => path.resolve(item.fileName) === path.resolve(session.airPath)) || document;
  await session.panel.webview.postMessage({ type: 'model', model: clientModel(session, current.getText()) });
  return current;
}

async function finishFrameEdit(session, document, message) {
  // Release the guarded frame form before disk persistence. A failed or delayed
  // save must never strand the viewer in its "current frame-field edit" state.
  await session.panel.webview.postMessage({ type: 'frameEditApplied', ...message });
  return autoSaveAirDocument(session, document);
}

async function autoSaveAirDocument(session, document) {
  const scope = vscode.Uri?.file ? vscode.Uri.file(session.airPath) : undefined;
  const enabled = Boolean(vscode.workspace.getConfiguration?.('ikemenZss', scope)?.get('autoSave', false));
  if (!enabled) return null;
  const result = await saveSourceDocument(document, path.basename(session.airPath));
  await session.panel.webview.postMessage({ type: 'sourceSaveStatus', state: sourceState(document, path.basename(session.airPath)), message: result.message });
  if (!result.ok) throw new Error(result.message);
  return result;
}

function actionMutationBaseline(document) { return { version: document.version, text: document.getText() }; }
function requireActionMutationBaseline(document, baseline) {
  return requireActionMutationSnapshot(baseline, { version: document.version, text: document.getText() });
}
async function applyActionMutation(session, document, patches, message) {
  const nextText = applyActionPatches(document.getText(), patches), nextModel = session.actionMutationModel ? session.actionMutationModel(nextText) : clientModel(session, nextText), edit = new vscode.WorkspaceEdit();
  for (const patch of [...patches].sort((a, b) => b.start - a.start)) edit.replace(document.uri, new vscode.Range(document.positionAt(patch.start), document.positionAt(patch.end)), patch.text);
  if (!await vscode.workspace.applyEdit(edit)) throw new Error('VS Code rejected the AIR action edit.');
  // The preflight model was built before applyEdit; publish the committed dirty state.
  const committedModel={...nextModel,sourceState:sourceState(document,path.basename(session.airPath))};
  if(session.lastClientModel===nextModel)session.lastClientModel=committedModel;
  await session.panel.webview.postMessage({ type: 'model', model: committedModel });
  const completionType = message.completionType || 'actionMutationApplied', completion = { ...message }; delete completion.completionType;
  await session.panel.webview.postMessage({ type: completionType, ...completion });
  if (completionType === 'actionMutationApplied' && completion.action !== undefined && completion.action !== null) await session.panel.webview.postMessage({ type: 'selectAction', action: Number(completion.action) });
}

function frameMoveBlockers(session, action, from, to) {
  if (session.frameMoveBlockers) return session.frameMoveBlockers(action, from, to);
  const elements = new Set([Number(from) + 1, Number(to) + 1]), blockers = [];
  for (const entry of readPushboxPlan(session.airPath).overrides || []) if (entry.action === Number(action) && elements.has(entry.element)) blockers.push(`saved push-box plan on element ${entry.element}`);
  for (const entry of readRuntimePlan(session.airPath).entries || []) if (entry.action === Number(action) && elements.has(entry.element)) blockers.push(`saved ${entry.kind} plan on element ${entry.element}`);
  const prefix = `${path.resolve(session.airPath).replace(/\\/g, '/').toLowerCase()}|${Number(action)}|`;
  for (const key of Object.keys(runtimeDraftStore.read(session.airPath))) {
    if (!key.startsWith(prefix)) continue;
    const element = Number(key.slice(prefix.length).split('|')[0]);
    if (elements.has(element)) blockers.push(`unfinished frame plan on element ${element}`);
  }
  return [...new Set(blockers)];
}

function actionDeletionBlockers(session, numbers) {
  const actions = new Set((numbers || []).map(Number)), blockers = [];
  for (const entry of readPushboxPlan(session.airPath).overrides || []) if (actions.has(Number(entry.action))) blockers.push(`Action ${entry.action} has a saved push-box plan.`);
  for (const entry of readRuntimePlan(session.airPath).entries || []) if (actions.has(Number(entry.action))) blockers.push(`Action ${entry.action} has a saved ${entry.kind} frame plan.`);
  const root = `${path.resolve(session.airPath).replace(/\\/g, '/').toLowerCase()}|`;
  for (const key of Object.keys(runtimeDraftStore.read(session.airPath))) {
    if (!key.startsWith(root)) continue;
    const action = Number(key.slice(root.length).split('|')[0]);
    if (actions.has(action)) blockers.push(`Action ${action} has an unfinished frame-plan draft.`);
  }
  return [...new Set(blockers)];
}

async function actionNumberInput(title, value, baselineText, unavailable = []) {
  const used = new Set(actionSourceRanges(baselineText).map((item) => item.number)), blocked = new Set(unavailable.map(Number));
  const answer = await vscode.window.showInputBox({ title, value: String(value), validateInput: (text) => {
    const clean = String(text).trim(); if (!/^-?\d+$/.test(clean)) return 'Enter an explicit decimal whole-number AIR action ID.';
    const number = Number(clean); if (!Number.isSafeInteger(number) || number < -2147483648 || number > 2147483647) return 'Enter an AIR action ID from -2147483648 through 2147483647.';
    if (used.has(number) || blocked.has(number)) return `Action ${number} already exists.`;
    return null;
  } });
  return answer === undefined ? null : Number(String(answer).trim());
}

function nextActionNumber(ranges, preferred = 0) {
  const used = new Set((ranges || []).map((item) => item.number)), candidate = Number(preferred);
  if (Number.isSafeInteger(candidate) && candidate >= -2147483648 && candidate <= 2147483647 && !used.has(candidate)) return candidate;
  for (let offset = 0; offset <= used.size; offset += 1) if (!used.has(offset)) return offset;
  throw new Error('No unused AIR action number is available in the supported range.');
}

