async function importGifTimingHandoff(handoff = {}) {
  let airPath = String(handoff.airPath || '').trim();
  const activePath = vscode.window.activeTextEditor?.document?.fileName || '';
  if (!airPath && /\.air$/i.test(activePath)) airPath = activePath;
  if (!airPath) {
    const picked = await vscode.window.showOpenDialog({ title: 'Choose the AIR file that should receive the reviewed GIF timing', canSelectFiles: true, canSelectFolders: false, canSelectMany: false, filters: { 'IKEMEN/MUGEN animations': ['air'] } });
    if (!picked?.[0]) return;
    airPath = picked[0].fsPath;
  }
  const session = await openAirPreview(vscode.Uri.file(airPath), { preserveFocus: false, allowEmpty: true, action: Number.isInteger(Number(handoff.suggestedAction)) ? Number(handoff.suggestedAction) : undefined });
  if (!session) throw new Error('The AIR workspace could not be opened for GIF timing review.');
  if (handoff.expectedSffPath !== undefined && (!session.sffPath || path.resolve(session.sffPath).toLowerCase() !== path.resolve(handoff.expectedSffPath).toLowerCase())) throw new Error('The chosen AIR is not connected to the reviewed target SFF. Choose its assigned AIR or review the character DEF source links first.');
  return importGifToAir(session, handoff.suggestedAction, handoff);
}

