function reviewedFramePropertySequence(text, requests) {
  let output = String(text || ''); const plans = [];
  for (const request of requests) { const plan = airFramePropertyBatch.review(output, request); output = airFramePropertyBatch.applyReviewed(output, plan); plans.push(plan); }
  return { output, plans };
}

