    if(session.transferPinned&&session.transferRole==='source'&&!pinnedSourceMessageAllowed(message)){session.panel.webview.postMessage({type:'error',operation:message.type,message:'The pinned AIR Transfer Source is read-only. Copy selected actions to the Destination or exit Transfer.'});return;}
    if(session.transferPinned&&session.transferRole==='source'&&(sourceMutationTypes.has(message.type)||['saveAir','saveAirAs','runtimeDraftSync','saveRuntime','removeRuntime'].includes(message.type))){session.panel.webview.postMessage({type:'error',operation:message.type,message:'The pinned AIR Transfer Source is read-only. Copy selected actions to the Destination or exit Transfer.'});return;}
