    const changed = path.resolve(event.document.fileName), relevant = session.defPath && path.resolve(session.defPath) === changed || session.constantsPath && path.resolve(session.constantsPath) === changed || (session.sourcePaths || []).some((filename) => path.resolve(filename) === changed);
