  const changed = new Set((files || []).map(item => path.resolve(typeof item === 'string' ? item : item?.fsPath || '')));
  for (const session of panels.values()) {
    if (changed.has(path.resolve(session.airPath))) { revokeAirCollisionEditReview(session, { terminal: true }); session.panel.webview.postMessage({ type: 'collisionEditUnavailable', message: 'This AIR source was removed or renamed. Reopen the valid AIR path before editing collisions.' }); continue; }
    const relevant = [session.defPath, session.constantsPath, ...(session.sourcePaths || [])].filter(Boolean).some(filename => changed.has(path.resolve(filename)));
    if (!relevant) continue;
    const airDocument = vscode.workspace.textDocuments.find(item => !item.isClosed && airPanelKey(item.fileName) === airPanelKey(session.airPath));
    if (!airDocument) continue;
    try { session.panel.webview.postMessage({ type: 'model', model: clientModel(session, airDocument.getText()) }); }
    catch (error) { session.panel.webview.postMessage({ type: 'error', message: `AIR References became unavailable: ${error.message}` }); }
  }
